std::vector<std::pair<CGAL::Triangulation_face_base_2<Triangulation>::Face_handle,
                      bool>> face_queue;
std::unordered_map<CGAL::Triangulation_face_base_2<Triangulation>::Face_handle,
                   bool, CGAL::Triangulation_face_base_2<Triangulation>::Hash> face_labels;

// Initialize all faces as unlabeled
for (auto face : triangulation.finite_faces()) {
    face_labels[face] = std::numeric_limits<bool>::quiet_NaN();
}

// Label boundary faces using odd-even rule
for (auto edge : triangulation.finite_edges()) {
    if (triangulation.is_constrained(edge)) continue;
    if (triangulation.is_infinite(edge)) {
        auto f1 = edge->first;
        auto f2 = edge->second;
        bool label = std::isnan(face_labels[f1]) ? false : face_labels[f1];
        face_labels[f1] = label;
        face_labels[f2] = !label;
        face_queue.emplace_back(f1, label);
        face_queue.emplace_back(f2, !label);
    }
}

// Propagate labels using BFS
while (!face_queue.empty()) {
    auto [current_face, current_label] = face_queue.back();
    face_queue.pop_back();

    for (auto neighbor : current_face->neighbors()) {
        if (std::isnan(face_labels[neighbor])) {
            face_labels[neighbor] = current_label;
            face_queue.emplace_back(neighbor, current_label);
        } else if (face_labels[neighbor] != current_label) {
            // Conflict detected - this shouldn't happen in a valid triangulation
            // but we'll handle it by marking both faces as unlabeled
            face_labels[current_face] = std::numeric_limits<bool>::quiet_NaN();
            face_labels[neighbor] = std::numeric_limits<bool>::quiet_NaN();
        }
    }
}

// Apply labels to the triangulation
for (auto face : triangulation.finite_faces()) {
    if (!std::isnan(face_labels[face])) {
        triangulation.set_label(face, face_labels[face] ? CGAL::INTERIOR : CGAL::EXTERIOR);
    } else {
        // For unlabeled faces (shouldn't happen in valid triangulation)
        triangulation.set_label(face, CGAL::INTERIOR);
    }
}
// END_CODE

